<?php
namespace Delnavazan\Platform\Portals;
final class PortalPublicActionController {
    public static function register():void { register_rest_route('delnavazan-platform/v1','/portal/join',array('methods'=>'GET','permission_callback'=>'__return_true','callback'=>array(__CLASS__,'join'))); register_rest_route('delnavazan-platform/v1','/portal/absence',array('methods'=>'GET','permission_callback'=>'__return_true','callback'=>array(__CLASS__,'absence'))); register_rest_route('delnavazan-platform/v1','/portal/absence/confirm',array('methods'=>'POST','permission_callback'=>'__return_true','callback'=>array(__CLASS__,'absence'))); }
    private static function refused(\Throwable $e):\WP_REST_Response { global $wpdb; $table=$wpdb->prefix.'dzn_portal_access_denials'; $reason=in_array($e->getMessage(),PortalRule::REASON_CODES,true)?$e->getMessage():'portal_capability_unknown'; if($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$table)))$wpdb->insert($table,array('uid'=>substr(hash('sha256',wp_generate_uuid4()),0,26),'surface'=>'portal_public_join','target_kind'=>'capability','reason_code'=>$reason,'request_fingerprint_digest'=>hash('sha256',wp_json_encode($_REQUEST)),'occurred_at'=>gmdate('Y-m-d H:i:s'),'created_at'=>gmdate('Y-m-d H:i:s')));$response=new \WP_REST_Response(array('code'=>'portal_action_unavailable'),404);$response->header('Cache-Control','no-store');return $response; }
    public static function join(\WP_REST_Request $request):\WP_REST_Response { try { if((string)get_option(PortalRule::PUBLIC_ACTION_OPTION,'')!==PortalRule::PUBLIC_ACTION_ENABLED_VALUE)throw new \InvalidArgumentException('portal_route_disabled');$url=(new PortalCapabilityService())->join((string)$request->get_param('handle'),(string)$request->get_param('token'));$response=new \WP_REST_Response(null,302,array('Location'=>$url));$response->header('Referrer-Policy','no-referrer');$response->header('Cache-Control','no-store');return $response; } catch(\Throwable $e){return self::refused($e);} }
    public static function absence(\WP_REST_Request $request):\WP_REST_Response { try { if((string)get_option(PortalRule::PUBLIC_ACTION_OPTION,'')!==PortalRule::PUBLIC_ACTION_ENABLED_VALUE)throw new \InvalidArgumentException('portal_route_disabled'); throw new \InvalidArgumentException('portal_capability_unknown'); } catch(\Throwable $e){return self::refused($e);} }
}
